with open(session_file) as f:
    content = f.read()

# Extract grids from the session
def extract_grid(text):
    # Look for header line then grid rows
    header_match = re.search(r'(\w+) \((\d+)x(\d+)\):\s*(.*?)(?=\n\w+ \(|$)', text, re.DOTALL)
    if header_match:
        name, h, w, rows_text = header_match.groups()
        # Parse rows - they're space-separated numbers on each line
        lines = [l.strip() for l in rows_text.split('\n') if l.strip()]
        # Find first non-empty line after header (should be numbers)
        for i, line in enumerate(lines):
            if line and all(c.isdigit() or c in ' -' for c in line):
                rows = []
                for j in range(i, len(lines)):
                    row_str = lines[j]
                    if row_str and all(x.isdigit() for x in row_str.split()):
                        rows.append([int(x) for x in row_str.split()])
                    else:
                        break
                return {'name': name, 'dims': (h, w), 'grid': rows}
    return None

# Try to extract from user messages that contain grids
grids = []
for line in open(session_file):
    try:
        msg = json.loads(line.strip())
        if 'message' in msg and msg['message'].get('role') == 'user':
            for content in msg['message'].get('content', []):
                if content.get('type') == 'text':
                    txt = content.get('text', '')
                    if 'Test input' in txt or ('Demo pair' in txt):
                        # Split into blocks by pattern X (NxM):
                        blocks = re.split(r'(\d+)x(\d+):\s*\n?', txt)
                        for i in range(1, len(blocks), 2):
                            if i % 2 == 1:  # This is the dimension line like "10x10"
                                continue
                            block = blocks[i] if i < len(blocks) else ""
                            dims = re.match(r'(\d+)x(\d+)', block.replace(':', '').replace('\n', ''))
                            if dims:
                                h, w = int(dims.group(1)), int(dims.group(2))
                                grid_start = txt.find(block) + len(block)
                                grid_end = txt.find('\nWrong attempts', grid_start) if 'Wrong attempts' in txt[grid_start:] else txt.find('\nReply with', grid_start)
                                grid_text = txt[grid_start:grid_end].strip()
                                grid_data = extract_grid(grid_text)
                                if grid_data:
                                    grids.append(grid_data)
                                    print(f"\n{block}: {grid_data['grid']}")
    except Exception as e:
        pass

print(f"\nTotal grids found: {len(grids)}")

